// MIT. Transform retained customer response files without network or a buyer retry.
import { open, mkdir, writeFile, rename, rm } from 'node:fs/promises';
import { constants } from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import { resolve, basename, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { buildFacilityReport, renderFacilityCsv, renderFacilityHtml } from './report-core.mjs';

const HELP = 'node report.mjs --events RETAINED_GEOJSON [--events ANOTHER_GEOJSON] --facilities FACILITIES_JSON --out NEW_REPORT_DIRECTORY [--as-of UTC_ISO_TIME]';
async function read(path, maximum) {
  const selected = resolve(path);
  const handle = await open(selected, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const before = await handle.stat({bigint:true});
    if (!before.isFile() || before.size > BigInt(maximum))
      throw new TypeError('Use a regular input within the size limit: ' + selected);
    const bytes = Buffer.alloc(Number(before.size));
    let offset=0;
    while (offset < bytes.length) {
      const {bytesRead} = await handle.read(bytes, offset, bytes.length-offset, offset);
      if (!bytesRead) break;
      offset += bytesRead;
    }
    const after = await handle.stat({bigint:true});
    if (offset !== bytes.length || ['dev','ino','size','mtimeNs','ctimeNs'].some(key => before[key] !== after[key]))
      throw new Error('The input changed while being read: ' + selected);
    return {name:basename(selected),sha256:createHash('sha256').update(bytes).digest('hex'),
      document:JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes))};
  } finally { await handle.close(); }
}
export async function main(args = process.argv.slice(2)) {
  if (!args.length || args.includes('--help')) { console.log(HELP); return; }
  const options = {events:[]};
  for (let i=0; i<args.length; i+=2) {
    const name=args[i], value=args[i+1];
    if (!['--events','--facilities','--out','--as-of'].includes(name) || !value || value.startsWith('--'))
      throw new TypeError(HELP);
    if (name === '--events') options.events.push(value);
    else {
      if (Object.hasOwn(options,name)) throw new TypeError('Repeated option: ' + name);
      options[name]=value;
    }
  }
  if (!options.events.length || options.events.length > 16 || !options['--facilities'] || !options['--out'])
    throw new TypeError(HELP);
  if (options['--as-of'] && !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,3})?Z$/.test(options['--as-of']))
    throw new TypeError('--as-of needs an explicit UTC ISO timestamp.');
  const facilities=await read(options['--facilities'],1048576), inputs=[];
  for (const path of options.events) inputs.push(await read(path,67108864));
  const report=buildFacilityReport(inputs,facilities.document,{generatedAt:options['--as-of']});
  report.facilitySource={name:facilities.name,sha256:facilities.sha256};
  const output=resolve(options['--out']);
  // Reserve the final path exclusively; retain a private INCOMPLETE marker if a disk write fails.
  await mkdir(output,{mode:0o700});
  const marker=join(output,'INCOMPLETE');
  await writeFile(marker,'Report creation is incomplete. Use the retained input files to create a new output directory.\n',
    {flag:'wx',mode:0o600});
  const contents = {'report.json':JSON.stringify(report,null,2)+'\n',
    'facility-events.csv':renderFacilityCsv(report),'report.html':renderFacilityHtml(report)};
  for (const [name,content] of Object.entries(contents)) {
    const temporary=join(output,'.'+name+'.'+randomUUID());
    await writeFile(temporary,content,{flag:'wx',mode:0o600});
    await rename(temporary,join(output,name));
  }
  await rm(marker);
  console.log(JSON.stringify({directory:output,files:Object.keys(contents),counts:report.counts},null,2));
  return report;
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error => { console.error(error.message); process.exitCode=1; });

/**
 * SF85: import a genuine operator-provided HTTP response header dump.
 * Unlike capture.mjs this adapter makes NO network request and never asserts
 * that it established TLS or determined when the response was captured.
 * SPDX-License-Identifier: MIT
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { isAbsolute } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs as validateExistingCaptureArgs } from './capture.mjs';
import { parseHeaderTrace } from './header-trace.mjs';
import { inspectBytes } from '../sf84-mpp-market-intake/inspect.mjs';

export function parseImportArgs(argv) {
  const index = argv.indexOf('--headers-file');
  if (index < 0 || index + 1 >= argv.length || !argv[index + 1]
      || argv.lastIndexOf('--headers-file') !== index) {
    throw Object.assign(new Error('MISSING_OR_DUPLICATE_HEADERS_FILE'), { code: 'MISSING_OR_DUPLICATE_HEADERS_FILE' });
  }
  const headersFile = argv[index + 1];
  if (!isAbsolute(headersFile) || headersFile.includes('\0')) {
    throw Object.assign(new Error('HEADERS_FILE_MUST_BE_ABSOLUTE'), { code: 'HEADERS_FILE_MUST_BE_ABSOLUTE' });
  }
  const rest = [...argv.slice(0, index), ...argv.slice(index + 2)];
  const { target, method, out } = validateExistingCaptureArgs(rest);
  if (headersFile === out) {
    throw Object.assign(new Error('SOURCE_AND_OUTPUT_MUST_DIFFER'), { code: 'SOURCE_AND_OUTPUT_MUST_DIFFER' });
  }
  return { headersFile, target, method, out };
}

export function run(argv) {
  const args = parseImportArgs(argv);
  const trace = parseHeaderTrace(readFileSync(args.headersFile));
  const capture = {
    schema: 'scf.sf85.capture.v1',
    captureSource: 'operator-exported-http-response-headers',
    // A file import cannot establish when the original HTTP call occurred.
    collectedAtUtc: null,
    importedAtUtc: new Date().toISOString(),
    sourceHeaderSha256: trace.sourceHeaderSha256,
    sourceHeaderBytes: trace.sourceHeaderBytes,
    discardedPreludeBlocks: trace.discardedPreludeBlocks,
    url: args.target.href,
    // Asserted by the operator. The server response dump has no request line.
    method: args.method,
    requestMethodSource: 'operator-declared',
    status: trace.status,
    headers: trace.headers,
  };
  const bytes = Buffer.from(JSON.stringify(capture, null, 2) + '\n', 'utf8');
  const report = inspectBytes(bytes);
  // Fail before writing on malformed intake. Never clobber prior evidence.
  writeFileSync(args.out, bytes, { flag: 'wx', mode: 0o600 });
  return {
    originalCapture: args.out,
    sourceHeaderSha256: trace.sourceHeaderSha256,
    capturedSha256: report.capturedSha256,
    httpStatus: report.httpStatus,
    classification: report.classification,
    x402: { status: report.x402.status, optionCount: report.x402.offer?.optionCount ?? 0, error: report.x402.error },
    mpp: { status: report.mpp.status, challengeCount: report.mpp.challenges.length, error: report.mpp.error },
    review: report.review,
  };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  try { console.log(JSON.stringify(run(process.argv.slice(2)), null, 2)); }
  catch (error) {
    console.error('SF85_HEADER_IMPORT_ERROR: ' + (error.code ?? 'FILE_OR_RUNTIME_ERROR'));
    process.exitCode = 2;
  }
}

