const OPERATION = 'ASTRA-D76C-SCF-CACHE-POLICY-20261012';
const retained = ['ttlMs', 'maxEntries', 'maxBytes', 'maxEntryBytes'];
const retention = value => Object.fromEntries(retained.map(key => [key, value[key]]));
